/* Unit tests for agent/common, driven by the vectors generated by
 * docs/protocol/test-vectors/generate.py (an independent implementation). */
#include <stdio.h>
#include <string.h>

#include "ndp/ndp_agent.h"
#include "ndp/ndp_auth.h"
#include "ndp/ndp_frame.h"
#include "ndp/ndp_names.h"
